#include "pci.h"
unsigned pci_scan(pci_read_fn read,void*ctx,pci_visit_fn visit,void*arg){if(!read||!visit)return 0;unsigned count=0;for(unsigned b=0;b<256;b++)for(unsigned d=0;d<32;d++){uint32_t id=read(ctx,b,d,0,0);if((id&65535)==65535)continue;unsigned h=read(ctx,b,d,0,12)>>16&255;unsigned limit=(h&128)?8:1;for(unsigned f=0;f<limit;f++){if(f)id=read(ctx,b,d,f,0);if((id&65535)==65535)continue;uint32_t cls=read(ctx,b,d,f,8);struct pci_function p={(uint8_t)b,(uint8_t)d,(uint8_t)f,(uint8_t)(cls>>24),(uint8_t)(cls>>16),(uint8_t)(cls>>8),(uint8_t)(f?read(ctx,b,d,f,12)>>16:h),(uint16_t)id,(uint16_t)(id>>16)};count++;if(!visit(arg,&p))return count;}}return count;}
